def para(t):return d.add_paragraph(t)
def heading(t):d.add_heading(t,level=1)
def link(p,label,url):
    h=OxmlElement('w:hyperlink');h.set(qn('r:id'),p.part.relate_to(url,RT.HYPERLINK,is_external=True))
    r=OxmlElement('w:r');pr=OxmlElement('w:rPr');sz=OxmlElement('w:sz');sz.set(qn('w:val'),'22');pr.append(sz)
    u=OxmlElement('w:u');u.set(qn('w:val'),'single');pr.append(u);r.append(pr)
    t=OxmlElement('w:t');t.text=label;r.append(t);h.append(r);p._p.append(h)

d.add_paragraph('Структурная схема мотортестера',style='Title')
p=d.add_paragraph('Описание блоков и принятые границы проекта')
p.paragraph_format.first_line_indent=Mm(0);p.paragraph_format.space_after=Pt(10)
para('Схема Э1 показывает укрупнённую структуру конечного одноканального прибора на STM32F103C8T6 с ёмкостным съёмом сигнала зажигания и приложением Windows 10. Шесть пронумерованных блоков описывают основные функции. Схема является проектной: она не утверждает, что прибор собран, испытан или допущен к высоковольтному подключению.')
para('Сплошные линии обозначают внутренние функциональные связи. Штрихпунктиром показаны внешние объекты и их связи: система зажигания, ПК, источник питания. Стрелки указывают направление сигнала; двусторонние стрелки относятся к обмену данными и командами. Это не схема монтажа или распиновки.')

heading('1 Ёмкостный датчик')
para('Получает сигнал через электрическое поле вокруг изолированного высоковольтного провода. Непосредственное электрическое соединение с жилой не предусматривается. Геометрия датчика, кабель и входная нагрузка влияют на форму и масштаб сигнала, поэтому конкретная конструкция и калибровка ещё должны быть выбраны. Датчик сам по себе не доказывает гальваническую развязку всей системы.')

heading('2 Входной аналоговый узел')
para('Объединяет защиту от перегрузок, высокоомное согласование с датчиком, масштабирование, смещение уровня, аналоговую фильтрацию и согласование с входом АЦП. Такое объединение сохраняет простоту структурной схемы; отдельные резисторы, конденсаторы и усилители здесь не показываются. Ранее подготовленные варианты A и B предназначены для низковольтных проверок и не являются готовым входом для датчика зажигания.')

heading('3 Узел регистрации на STM32F103C8T6')
para('Встроенный 12-разрядный АЦП преобразует входной сигнал в цифровые отсчёты. Таймер задаёт выборки, DMA переносит данные в память, а прошивка управляет буфером, сбором отсчётов, предысторией и передачей результата. Эти внутренние функции объединены в один блок, поскольку относятся к одному микроконтроллеру. Фактические частота, полоса и точность готового прибора подтверждаются отдельно измерениями.')

heading('4 Интерфейс native USB FS')
para('Передаёт осциллограммы и метаданные на компьютер и принимает команды управления. Это функция встроенного USB-контроллера STM32 и его аппаратного соединения, а не отдельный преобразователь USB–UART. На схеме интерфейс выделен для наглядности. Гальваническую развязку связи необходимо проектировать вместе с питанием и всеми другими путями общей земли; её наличие пока не утверждается.')

heading('5 ПК и приложение Windows 10')
para('Внешний компьютер задаёт параметры захвата, отображает осциллограммы, сохраняет исходные отсчёты и метаданные и повторно открывает записи. Требуется независимый масштаб по времени и амплитуде, изменяющий только вид графика, а не исходные данные или калибровку. В приложении предусматриваются русский интерфейс и справка. Машинное обучение и автоматическая постановка диагноза в первую версию не входят. Наличие блока на схеме не означает завершённую проверку Windows-сборки или реального USB-подключения.')

heading('6 Питание и опорные цепи')
para('Формирует необходимые напряжения и опорные уровни, обеспечивает фильтрацию питания аналоговой и цифровой частей. Конкретный источник, схема подачи питания и развязка ещё не выбраны; стрелка от низковольтного источника обозначает функцию, а не готовое подключение. Текущий USB-вариант использует питание от шины и фиксированную подтяжку D+, поэтому нельзя без проверки добавлять параллельное внешнее питание платы.')
para('Имеющийся ноутбучный адаптер с заявленным номиналом 19 В питает модуль ZK-4KX. Эта цепь не назначена источником питания платы на данной схеме. Подавать 19 В непосредственно на STM32 или его плату нельзя. Допустимые входы и уровни определяются после проверки конкретной платы и топологии питания.')

heading('Режимы записи и границы изменения')
para('Предусмотрены две пользовательские функции: «Запись сейчас» и однократный захват искрового события. Первая должна начинать запись после получения команды микроконтроллером, без ожидания внешней отметки. По уточнению владельца однократный захват должен сохранять один разряд целиком, с горением и затуханием, затем останавливаться. Параметры окна и проверка полноты разряда ещё разрабатываются. Это целевое требование, а не утверждение о завершённом изменении программы.')
para('Один захват не обязательно равен периоду между двумя искрами. Кнопка приложения также не обеспечивает точной временной привязки к команде отдельного стенда. Отсутствие зарегистрированного сигнала само по себе не подтверждает неисправность катушки. Внешний вход запуска из структуры удалён; встроенные способы обнаружения события и совместимость протокола проверяются до изменения кода.')
heading('Последовательность работы')
para('Ёмкостный датчик → аналоговый узел → АЦП и буфер STM32 → USB → приложение. Команды оператора поступают в обратном направлении через USB. Стенд разрабатывается отдельно; внешняя синхронизация в мотортестере исключена по уточнению владельца от 12.10.2026. ST-Link используется для сервисной прошивки и отладки; в основной измерительный путь он не входит и поэтому не перегружает схему отдельным блоком.')

heading('Оформление и оставшиеся реквизиты')
para('Чертёж выполнен на одном листе А3, 420 × 297 мм, с рамкой 20 мм слева и 5 мм с остальных сторон. Основная надпись имеет форму 1 и размер 185 × 55 мм. Использованы код Э1, прямоугольные функциональные блоки, линии связей 0,35 мм и шрифт OpenGOST типа Б без наклона. В PDF шрифт встроен, в SVG надписи преобразованы в векторные контуры. При печати выбирать масштаб 100 %, без подгонки под страницу.')
para('МТ.00.00.000 Э1 — временное рабочее обозначение, а не присвоенный кафедрой шифр диплома. Фамилии, подписи и другие неизвестные реквизиты оставлены для заполнения. Учебное заведение может потребовать свой шифр, основную надпись или дополнительные реквизиты. Это не меняет показанный состав блоков.')
para('Перед высоковольтным применением необходимо проверить датчик, перегрузочную стойкость и полосу входа, питание, все пути земли и развязки, паспорт платы и низковольтный захват. Структурная схема этих испытаний не заменяет.')

heading('Основания оформления')
p=para('Для Казахстана проверены действующие записи каталога КазСтандарт на 12.10.2026. Геометрия и правила схем сверены с текстами соответствующих стандартов. Ниже приведены ссылки на официальные карточки; утверждение кафедрой не подразумевается.')
refs=[('ГОСТ 2.701-2008 — виды и типы схем','38206'),('ГОСТ 2.702-2011 — электрические схемы','46766'),('ГОСТ 2.104-2006 — основные надписи','15565'),('ГОСТ 2.301-68 — форматы','14504'),('ГОСТ 2.303-68 — линии','14506'),('ГОСТ 2.304-81 — чертёжные шрифты','14507')]
